<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Falling Sand Sandbox</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #111318;
    --panel: #1d2028;
    --panel2: #252a34;
    --text: #e8ecf2;
    --muted: #9aa4b2;
    --accent: #80cbc4;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    background:
      radial-gradient(circle at 50% 0%, #252b38 0, var(--bg) 52%),
      var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }

  main {
    width: min(94vw, 650px);
    padding: 24px;
    border-radius: 22px;
    background: rgba(29, 32, 40, .96);
    box-shadow: 0 22px 70px rgba(0, 0, 0, .45);
  }

  h1 {
    margin: 0 0 5px;
    text-align: center;
    font-size: 25px;
    letter-spacing: .5px;
  }

  .subtitle {
    margin: 0 0 19px;
    text-align: center;
    color: var(--muted);
    font-size: 13px;
  }

  #sand {
    display: block;
    width: min(92vw, 560px);
    height: min(92vw, 560px);
    min-width: 400px;
    min-height: 400px;
    margin: 0 auto;
    border: 2px solid #3a414e;
    border-radius: 12px;
    background: #0a0c10;
    cursor: crosshair;
    touch-action: none;
    image-rendering: pixelated;
  }

  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 9px;
    justify-content: center;
    margin-top: 19px;
  }

  button {
    border: 0;
    border-radius: 9px;
    padding: 11px 15px;
    color: var(--text);
    background: var(--panel2);
    box-shadow: 0 3px 7px rgba(0, 0, 0, .28);
    cursor: pointer;
    font: inherit;
    font-size: 14px;
    transition: transform .12s, filter .12s, background .12s;
  }

  button:hover { filter: brightness(1.18); }
  button:active { transform: translateY(2px); }
  button.selected {
    color: #102321;
    background: var(--accent);
    box-shadow: 0 0 0 2px #b2dfdb, 0 4px 12px rgba(128, 203, 196, .28);
  }

  #clear {
    background: #70464c;
  }

  .legend {
    margin-top: 14px;
    text-align: center;
    color: var(--muted);
    font-size: 12px;
  }
</style>
</head>
<body>
<main>
  <h1>Falling Sand</h1>
  <p class="subtitle">Paint a world and watch it come alive</p>

  <canvas id="sand" width="500" height="500" aria-label="Falling sand simulation"></canvas>

  <div class="controls">
    <button id="mat-sand" class="selected">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Eraser</button>
    <button id="clear">Clear</button>
  </div>
  <div class="legend">Drag on the canvas to paint</div>
</main>

<script>
(() => {
  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d", { alpha: false });
  const w = 100, h = 100;
  const cells = new Array(w * h).fill("empty");
  const moved = new Uint8Array(w * h);
  const materials = ["empty", "sand", "water", "wall", "acid"];
  let selected = "sand";
  let seed = 0x9e3779b9;
  let drawing = false;

  const colors = {
    empty: "#0a0c10",
    sand: "#e6bd69",
    water: "#4ba3df",
    wall: "#737b87",
    acid: "#a7df58"
  };

  function index(x, y) { return y * w + x; }
  function inside(x, y) { return x > 0 && x < w - 1 && y >= 0 && y < h - 1; }

  function randomBit() {
    seed ^= seed << 13;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    seed >>>= 0;
    return seed & 1;
  }

  function paintCell(x, y, material) {
    if (x >= 0 && x < w && y >= 0 && y < h && materials.includes(material)) {
      cells[index(x, y)] = material;
    }
  }

  function moveCell(sx, sy, dx, dy) {
    const from = index(sx, sy);
    const to = index(dx, dy);
    cells[to] = cells[from];
    cells[from] = "empty";
    moved[to] = 1;
  }

  function displaceDown(sx, sy, dx, dy) {
    const target = cells[index(dx, dy)];
    if (target === "empty") {
      moveCell(sx, sy, dx, dy);
      return true;
    }

    if ((target === "water" || target === "acid") && inside(dx, dy)) {
      const dirs = randomBit() ? [1, -1] : [-1, 1];
      for (const dir of dirs) {
        const lx = dx + dir;
        if (inside(lx, dy) && cells[index(lx, dy)] === "empty") {
          cells[index(lx, dy)] = target;
          moved[index(lx, dy)] = 1;
          cells[index(dx, dy)] = cells[index(sx, sy)];
          cells[index(sx, sy)] = "empty";
          moved[index(dx, dy)] = 1;
          return true;
        }
      }
    }
    return false;
  }

  function tryFall(x, y, material) {
    if (displaceDown(x, y, x, y + 1)) return true;

    const dirs = randomBit() ? [1, -1] : [-1, 1];
    for (const dir of dirs) {
      const nx = x + dir, ny = y + 1;
      if (inside(nx, ny) && cells[index(nx, ny)] === "empty") {
        moveCell(x, y, nx, ny);
        return true;
      }
    }
    return false;
  }

  function dissolveNearby(x, y) {
    const candidates = [];
    const checks = [[x, y + 1], [x - 1, y], [x + 1, y]];
    for (const [nx, ny] of checks) {
      if (inside(nx, ny)) {
        const value = cells[index(nx, ny)];
        if (value === "sand" || value === "wall") candidates.push([nx, ny]);
      }
    }
    if (candidates.length) {
      const target = candidates[seed % candidates.length];
      cells[index(target[0], target[1])] = "empty";
    }
  }

  function step() {
    moved.fill(0);

    for (let y = h - 2; y >= 0; y--) {
      for (let x = 1; x < w - 1; x++) {
        const i = index(x, y);
        const material = cells[i];
        if (moved[i] || material === "empty" || material === "wall") continue;

        if (material === "acid") dissolveNearby(x, y);

        if (tryFall(x, y, material)) continue;

        if (material === "water" || material === "acid") {
          const dirs = randomBit() ? [1, -1] : [-1, 1];
          for (const dir of dirs) {
            const nx = x + dir;
            if (inside(nx, y) && cells[index(nx, y)] === "empty") {
              moveCell(x, y, nx, y);
              break;
            }
          }
        }
      }
    }
  }

  function render() {
    const cw = canvas.width / w, ch = canvas.height / h;
    ctx.fillStyle = colors.empty;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const value = cells[index(x, y)];
        if (value !== "empty") {
          ctx.fillStyle = colors[value];
          ctx.fillRect(x * cw, y * ch, cw + .5, ch + .5);
        }
      }
    }
  }

  function tick(n = 1) {
    n = Math.max(0, Math.floor(Number(n) || 0));
    for (let i = 0; i < n; i++) step();
    render();
  }

  function clear() {
    cells.fill("empty");
    render();
  }

  window.sim = {
    w, h, tick,
    get(x, y) {
      return x >= 0 && x < w && y >= 0 && y < h ? cells[index(x, y)] : "empty";
    },
    set(x, y, material) {
      if (x >= 0 && x < w && y >= 0 && y < h && materials.includes(material)) {
        cells[index(x, y)] = material;
        render();
      }
    },
    clear
  };

  function canvasPosition(event) {
    const rect = canvas.getBoundingClientRect();
    return [
      Math.floor((event.clientX - rect.left) / rect.width * w),
      Math.floor((event.clientY - rect.top) / rect.height * h)
    ];
  }

  function paint(event) {
    const [x, y] = canvasPosition(event);
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) paintCell(x + dx, y + dy, selected);
    }
    render();
  }

  canvas.addEventListener("pointerdown", event => {
    drawing = true;
    canvas.setPointerCapture(event.pointerId);
    paint(event);
  });
  canvas.addEventListener("pointermove", event => { if (drawing) paint(event); });
  canvas.addEventListener("pointerup", () => { drawing = false; });
  canvas.addEventListener("pointercancel", () => { drawing = false; });

  for (const material of materials) {
    const button = document.getElementById("mat-" + material);
    button.addEventListener("click", () => {
      selected = material;
      document.querySelectorAll("[id^='mat-']").forEach(b => b.classList.remove("selected"));
      button.classList.add("selected");
    });
  }

  document.getElementById("clear").addEventListener("click", clear);

  function animate() {
    tick(1);
    requestAnimationFrame(animate);
  }

  render();
  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
